a:1:{i:1;s:5082:"
<div class="wp_syntax" style="position:relative;"><table><tr><td class="code"><pre class="powershell" style="font-family:monospace;"><span style="color: pink;">&amp;</span>lt;<span style="color: #008000;">############################################## File: GetAllEndpoints.ps1 Author: Thomas LaRock, http://thomaslarock.com/contact-me/ http://thomaslarock.com/2015/05/get-all-endpoints-for-vms-in-an-azure-subscription Summary: This script will loop through all the virtual machines in an Azure subscription and report on the assigned endpoints. Date: May 11th, 2015 You may alter this code for your own purposes. You may republish altered code as long as you give due credit. THIS CODE AND INFORMATION IS PROVIDED &quot;AS IS&quot; WITHOUT WARRANTY OF ANY KIND, EITHER EXPRESSED OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE IMPLIED WARRANTIES OF MERCHANTABILITY AND/OR FITNESS FOR A PARTICULAR PURPOSE. ##############################################&amp;gt;</span>
&nbsp;
<span style="color: pink;">&amp;</span>lt;<span style="color: #008000;"># We are going to loop through all VM's in this subscription. However, if you want to filter for a subset, perhaps by name, you could use something like: #$VMlist = Get-AzureVM | Where-Object { ($_.Name -ilike “something”) } But we don't want to filter for our example, so we just grab all VMs and build an array #&amp;gt;</span>
&nbsp;
<span style="color: #800080;">$VMlist</span> <span style="color: pink;">=</span> Get<span style="color: pink;">-</span>AzureVM
&nbsp;
<span style="color: pink;">&amp;</span>lt;<span style="color: #008000;"># We will now loop through each VM in the array #&amp;gt;</span>
&nbsp;
<span style="color: #0000FF;">foreach</span> <span style="color: #000000;">&#40;</span><span style="color: #800080;">$VMServiceName</span> <span style="color: #0000FF;">in</span> <span style="color: #800080;">$VMlist</span><span style="color: #000000;">&#41;</span> <span style="color: #000000;">&#123;</span>
&nbsp;
    <span style="color: #800080;">$obj</span> <span style="color: pink;">=</span> Get<span style="color: pink;">-</span>AzureVM <span style="color: pink;">-</span>ServiceName <span style="color: #800080;">$VMServiceName</span>.ServiceName <span style="color: #008080; font-style: italic;">-Name</span> <span style="color: #800080;">$VMServiceName</span>.Name <span style="color: pink;">|</span> Get<span style="color: pink;">-</span>AzureEndpoint 
&nbsp;
    <span style="color: #800080;">$Output</span> <span style="color: pink;">=</span> <span style="color: #008080; font-weight: bold;">New-Object</span> PSObject 
    <span style="color: #800080;">$Output</span> <span style="color: pink;">|</span> <span style="color: #008080; font-weight: bold;">Add-Member</span> VMName <span style="color: #800080;">$VMServiceName</span>.Name    
    <span style="color: #800080;">$Output</span> <span style="color: pink;">|</span> <span style="color: #008080; font-weight: bold;">Add-Member</span> EndpointNames <span style="color: #800080;">$obj</span>.Name   
    <span style="color: #800080;">$Output</span> <span style="color: pink;">|</span> <span style="color: #008080; font-weight: bold;">Add-Member</span> Endpoints <span style="color: #800080;">$obj</span>.LocalPort
&nbsp;
    <span style="color: #008080; font-weight: bold;">Write-Output</span> <span style="color: #800080;">$Output</span> 
    <span style="color: #000000;">&#125;</span></pre></td></tr></table><p class="theCode" style="display:none;">&amp;lt;############################################## File: GetAllEndpoints.ps1 Author: Thomas LaRock, http://thomaslarock.com/contact-me/ http://thomaslarock.com/2015/05/get-all-endpoints-for-vms-in-an-azure-subscription Summary: This script will loop through all the virtual machines in an Azure subscription and report on the assigned endpoints. Date: May 11th, 2015 You may alter this code for your own purposes. You may republish altered code as long as you give due credit. THIS CODE AND INFORMATION IS PROVIDED &quot;AS IS&quot; WITHOUT WARRANTY OF ANY KIND, EITHER EXPRESSED OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE IMPLIED WARRANTIES OF MERCHANTABILITY AND/OR FITNESS FOR A PARTICULAR PURPOSE. ##############################################&amp;gt;

&amp;lt;# We are going to loop through all VM's in this subscription. However, if you want to filter for a subset, perhaps by name, you could use something like: #$VMlist = Get-AzureVM | Where-Object { ($_.Name -ilike “something”) } But we don't want to filter for our example, so we just grab all VMs and build an array #&amp;gt;

$VMlist = Get-AzureVM

&amp;lt;# We will now loop through each VM in the array #&amp;gt;

foreach ($VMServiceName in $VMlist) {

    $obj = Get-AzureVM -ServiceName $VMServiceName.ServiceName -Name $VMServiceName.Name | Get-AzureEndpoint 

    $Output = New-Object PSObject 
    $Output | Add-Member VMName $VMServiceName.Name    
    $Output | Add-Member EndpointNames $obj.Name   
    $Output | Add-Member Endpoints $obj.LocalPort

    Write-Output $Output 
    }</p></div>
";}

