    <span style="color: #800080;">$Output</span> <span style="color: pink;">|</span> <span style="color: #008080; font-weight: bold;">Add-Member</span> EndpointNames <span style="color: #800080;">$obj</span>.Name   
    <span style="color: #800080;">$Output</span> <span style="color: pink;">|</span> <span style="color: #008080; font-weight: bold;">Add-Member</span> Endpoints <span style="color: #800080;">$obj</span>.LocalPort
&nbsp;
    <span style="color: #008080; font-weight: bold;">Write-Output</span> <span style="color: #800080;">$Output</span> 
    <span style="color: #000000;">&#125;</span></pre></td></tr></table><p class="theCode" style="display:none;">&amp;lt;############################################## File: GetAllEndpoints.ps1 Author: Thomas LaRock, http://thomaslarock.com/contact-me/ http://thomaslarock.com/2015/05/get-all-endpoints-for-vms-in-an-azure-subscription Summary: This script will loop through all the virtual machines in an Azure subscription and report on the assigned endpoints. Date: May 11th, 2015 You may alter this code for your own purposes. You may republish altered code as long as you give due credit. THIS CODE AND INFORMATION IS PROVIDED &quot;AS IS&quot; WITHOUT WARRANTY OF ANY KIND, EITHER EXPRESSED OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE IMPLIED WARRANTIES OF MERCHANTABILITY AND/OR FITNESS FOR A PARTICULAR PURPOSE. ##############################################&amp;gt;

&amp;lt;# We are going to loop through all VM's in this subscription. However, if you want to filter for a subset, perhaps by name, you could use something like: #$VMlist = Get-AzureVM | Where-Object { ($_.Name -ilike “something”) } But we don't want to filter for our example, so we just grab all VMs and build an array #&amp;gt;

$VMlist = Get-AzureVM

&amp;lt;# We will now loop through each VM in the array #&amp;gt;

foreach ($VMServiceName in $VMlist) {

    $obj = Get-AzureVM -ServiceName $VMServiceName.ServiceName -Name $VMServiceName.Name | Get-AzureEndpoint 

    $Output = New-Object PSObject 
    $Output | Add-Member VMName $VMServiceName.Name    
    $Output | Add-Member EndpointNames $obj.Name   
    $Output | Add-Member Endpoints $obj.LocalPort

    Write-Output $Output 
    }</p></div>
";}

